module alu8 (
    input logic [7:0] a,
    input logic [7:0] b,
    input logic [1:0] op,
    output logic [7:0] y,
    output logic zero
);
    always_comb begin
        y = 8'd0;

        case (op)
            2'b00: y = a + b;
            2'b01: y = a - b;
            2'b10: y = a & b;
            2'b11: y = a | b;
            default: y = 8'd0;
        endcase

        zero = (y == 8'd0);
    end
endmodule

